async function enhanceLocksWithOnChainData(locks, chainId, publicClient) {
  if (!publicClient || locks.length === 0) {
    return locks;
  }
  const contracts = getAbstractContracts(chainId);
  const votingEscrow = contracts?.votingEscrow;
  if (!votingEscrow) {
    return locks;
  }
  const validLocks = locks.map((lock) => {
    try {
      return { lock, tokenId: BigInt(lock.id) };
    } catch (error) {
      console.warn("Failed to parse veABX lock id for on-chain refresh:", lock.id, error);
      return null;
    }
  }).filter(
    (value) => value !== null
  );
  if (validLocks.length === 0) {
    return locks;
  }
  const managedRelayOwners = [];
  const ownerIndexMap = /* @__PURE__ */ new Map();
  locks.forEach((lock) => {
    if (!lock.managed || !lock.owner || !isAddress(lock.owner)) {
      return;
    }
    const ownerKey = lock.owner.toLowerCase();
    const existingIndex = ownerIndexMap.get(ownerKey);
    if (existingIndex === void 0) {
      managedRelayOwners.push({
        address: lock.owner,
        lockIds: [lock.id]
      });
      ownerIndexMap.set(ownerKey, managedRelayOwners.length - 1);
    } else {
      managedRelayOwners[existingIndex]?.lockIds.push(lock.id);
    }
  });
  const multicallContracts = validLocks.flatMap(({ tokenId }) => [
    {
      address: votingEscrow,
      abi: VOTING_ESCROW_READ_ABI,
      functionName: "locked",
      args: [tokenId]
    },
    {
      address: votingEscrow,
      abi: VOTING_ESCROW_READ_ABI,
      functionName: "balanceOfNFT",
      args: [tokenId]
    }
  ]);
  try {
    const results = await publicClient.multicall({
      allowFailure: true,
      contracts: multicallContracts
    });
    const updates = /* @__PURE__ */ new Map();
    validLocks.forEach(({ lock }, idx) => {
      const lockedResult = results[idx * 2];
      const votingPowerResult = results[idx * 2 + 1];
      const partial = {};
      if (lockedResult?.status === "success") {
        const tuple = lockedResult.result;
        const amountValue = Array.isArray(tuple) ? tuple[0] : tuple?.amount;
        const endValue = Array.isArray(tuple) ? tuple[1] : tuple?.end;
        const permanentValue = Array.isArray(tuple) ? tuple[2] : tuple?.isPermanent;
        if (typeof amountValue === "bigint") {
          partial.amount = amountValue.toString();
        }
        if (typeof endValue === "bigint") {
          partial.lockEnd = endValue.toString();
        }
        if (typeof permanentValue === "boolean") {
          partial.permanent = permanentValue;
        }
      }
      if (votingPowerResult?.status === "success") {
        const votingPower = votingPowerResult.result;
        if (typeof votingPower === "bigint") {
          partial.votingPower = votingPower.toString();
        }
      }
      if (Object.keys(partial).length > 0) {
        updates.set(lock.id, partial);
      }
    });
    if (managedRelayOwners.length > 0) {
      const nameResults = await publicClient.multicall({
        allowFailure: true,
        contracts: managedRelayOwners.map(({ address }) => ({
          address,
          abi: MANAGED_RELAY_NAME_ABI,
          functionName: "name"
        }))
      });
      nameResults.forEach((result, index) => {
        if (result?.status !== "success") {
          return;
        }
        const relayName = typeof result.result === "string" ? result.result : void 0;
        if (!relayName) {
          return;
        }
        const mappingEntry = managedRelayOwners[index];
        mappingEntry?.lockIds.forEach((lockId) => {
          const partial = updates.get(lockId) ?? {};
          partial.relayName = relayName;
          updates.set(lockId, partial);
        });
      });
    }
    if (updates.size === 0) {
      return locks;
    }
    return locks.map((lock) => {
      const partial = updates.get(lock.id);
      return partial ? { ...lock, ...partial } : lock;
    });
  } catch (error) {
    console.error("Failed to enhance veABX locks with on-chain data:", error);
    return locks;
  }
}
export function useVeABXUserLocks(owner, enabled = true, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["veabx-user-locks", owner?.toLowerCase(), chainId],
    queryFn: async () => {
      if (!owner) return [];
      const data = await fetchDataFromSubgraph(
        GET_USER_LOCKS_QUERY,
        { owner: owner.toLowerCase() },
        chainId
      );
      const locks = data?.veABXLocks || [];
      return enhanceLocksWithOnChainData(locks, chainId, publicClient);
    },
    enabled: enabled && !!owner,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useVeABXGlobals(enabled = true, chainId = UniverseChainId.Mainnet) {
  return useQuery({
    queryKey: ["veabx-globals", chainId],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(
        GET_VEABX_GLOBALS_QUERY,
        {},
        chainId
      );
      return data?.veABXGlobals || [];
    },
    enabled,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider data stale after 30 seconds
  });
}
export function useVeABXLock(lockId, enabled = true, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["veabx-lock", lockId, chainId],
    queryFn: async () => {
      if (!lockId) return null;
      const data = await fetchDataFromSubgraph(
        GET_SINGLE_LOCK_QUERY,
        { id: lockId },
        chainId
      );
      const lock = data?.veABXLock;
      if (!lock) return null;
      const [enhancedLock] = await enhanceLocksWithOnChainData([lock], chainId, publicClient);
      return enhancedLock ?? lock;
    },
    enabled: enabled && !!lockId,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
